export const COAST_JAPAN_B64 = '';

/** { coords, offsets }: coords is a Float32Array of [lon, lat] degree pairs; line k is points
 *  offsets[k] .. offsets[k + 1] - 1 (offsets is a Uint32Array of COAST_JAPAN_LINES + 1). Decodes on every call. */
export function decodeCoastJapan() {
  const bin = atob(COAST_JAPAN_B64);
  const coords = new Float32Array(COAST_JAPAN_POINTS * 2), offsets = new Uint32Array(COAST_JAPAN_LINES + 1);
  const hi = COAST_JAPAN_POINTS * 2;
  let p = 0, o = 0;
  for (let k = 0; k < COAST_JAPAN_LINES; k++) {
    offsets[k] = p;
    let x = 0, y = 0;
    for (let n = 0; n < COAST_JAPAN_LENGTHS[k]; n++, p++) {
      let dx = bin.charCodeAt(o) | (bin.charCodeAt(hi + o) << 8), dy = bin.charCodeAt(o + 1) | (bin.charCodeAt(hi + o + 1) << 8);
      o += 2;
      if (dx >= 32768) dx -= 65536;
      if (dy >= 32768) dy -= 65536;
      x += dx; y += dy;
      coords[2 * p] = COAST_JAPAN_LON0 + x * COAST_JAPAN_STEP;
      coords[2 * p + 1] = COAST_JAPAN_LAT0 + y * COAST_JAPAN_STEP;
    }
  }
  offsets[COAST_JAPAN_LINES] = p;
  return { coords, offsets };
}
